    h, w = len(grid), len(grid[0])
    # Separator color forms complete horizontal and vertical grid lines.
    sep = next((v for v in range(10)
                if any(all(x == v for x in row) for row in grid)
                and any(all(grid[r][c] == v for r in range(h)) for c in range(w))), None)
    if sep is None:
        return [row[:] for row in grid]
    row_lines = [r for r in range(h) if all(x == sep for x in grid[r])]
    col_lines = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    row_starts = [0] + [r + 1 for r in row_lines if r + 1 < h]
    col_starts = [0] + [c + 1 for c in col_lines if c + 1 < w]
    row_starts = [r for r in row_starts if r < h and (r == 0 or r - 1 in row_lines)]
    col_starts = [c for c in col_starts if c < w and (c == 0 or c - 1 in col_lines)]
    row_ends = [r - 1 for r in row_lines] + [h - 1]
    col_ends = [c - 1 for c in col_lines] + [w - 1]
    row_ends = [e for e in row_ends if e >= 0]
    col_ends = [e for e in col_ends if e >= 0]
    if not row_starts or not col_starts:
        return [row[:] for row in grid]
    rh = row_ends[0] - row_starts[0] + 1
    cw = col_ends[0] - col_starts[0] + 1

    # Extract the occupied shape from a non-marker cell panel.
    motif = None
    for r in row_starts:
        for c in col_starts[1:]:
            coords = [(dr, dc) for dr in range(rh) for dc in range(cw)
                      if grid[r + dr][c + dc] not in (0, sep)]
            if coords:
                motif = coords
                break
        if motif is not None:
            break
    if motif is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for ri, r in enumerate(row_starts):
        # The leftmost panel stores the color to use for this row of panels.
        marker = next((grid[r + dr][col_starts[0] + dc]
                       for dr in range(rh) for dc in range(cw)
                       if grid[r + dr][col_starts[0] + dc] not in (0, sep)), 0)
        for c in col_starts:
            for dr in range(rh):
                for dc in range(cw):
                    out[r + dr][c + dc] = 0
            for dr, dc in motif:
                out[r + dr][c + dc] = marker
    return out

